import{_ as s,c as a,o as t,ae as d}from"./chunks/framework.Cd-3tpCq.js";const m=JSON.parse('{"title":"Feature: Delayed/Unprompted Messages from Buddies","description":"","frontmatter":{},"headers":[],"relativePath":"dev/features/delayed-messages.md","filePath":"dev/features/delayed-messages.md"}'),l={name:"dev/features/delayed-messages.md"};function o(r,e,i,n,u,h){return t(),a("div",null,e[0]||(e[0]=[d('<h1 id="feature-delayed-unprompted-messages-from-buddies" tabindex="-1">Feature: Delayed/Unprompted Messages from Buddies <a class="header-anchor" href="#feature-delayed-unprompted-messages-from-buddies" aria-label="Permalink to &quot;Feature: Delayed/Unprompted Messages from Buddies&quot;">​</a></h1><p>The idea is that Buddies could send the user a message without necessarily needing them to send one first. There is at least a couple angles as far as the app&#39;s &quot;canon&quot; if you will:</p><ul><li>Buddy is busy: The user sends a message but the Buddy wouldn&#39;t be available contextually. <ul><li>I&#39;m not sure exactly what I mean here, probably get the decision whether to respond from the LLM anyway.</li></ul></li><li>Buddy reaches out: The Buddy was the last to speak and the user leaves their chat (unfocused is tricky, so likely still in-app at first) and the Buddy sends them a new message. <ul><li>The only way I can think to accomplish this would be to schedule a potential new message along with messages (maybe instruct to generate max 1 sentence), which would be thrown away when a new message comes in from the user.</li><li>Perhaps we could have an option to use ntfy.sh or similar to schedule a push notification? Would be tricky because you can&#39;t cancel the notification. <ul><li><a href="https://docs.ntfy.sh/publish/#scheduled-delivery" target="_blank" rel="noreferrer">https://docs.ntfy.sh/publish/#scheduled-delivery</a></li></ul></li></ul></li></ul><p>This feature would most likely be after we start using <a href="./json-mode.html">proper JSON mode</a></p>',4)]))}const p=s(l,[["render",o]]);export{m as __pageData,p as default};
